package com.bolt.stronghold3wrapper;

import android.app.Activity;
import android.os.Bundle;
import android.view.SurfaceView;
import android.view.WindowManager;
import java.io.File;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.FileInputStream;
import java.io.FileOutputStream;

/**
 * MainActivity for the Stronghold 3 Android wrapper.
 * Auto-generated by Bolt Wrapper Builder.
 *
 * Flow:
 *  1. On first launch, copy assets/rootfs.tar.xz to app files dir and run init_env.sh
 *  2. On subsequent launches, run start_stronghold3.sh which extracts Wine + DXVK
 *     and launches Stronghold3.exe inside the Wine prefix via Box86.
 *  3. Hosts a SurfaceView viewport that the X11/DXVK compositor renders into, and
 *     exposes an RTS overlay (left/right click toggle, marquee select, pinch-zoom,
 *     two-finger pan and a hotkey bar).
 */
public class MainActivity extends Activity {

    private static final String TAG = "SH3Wrapper";
    private static final String APP_ROOT = "/data/data/com.bolt.stronghold3wrapper";
    private static final String ROOTFS_DIR = APP_ROOT + "/rootfs";
    private static final String MARKER = ROOTFS_DIR + "/.extracted";

    private SurfaceView surfaceView;
    private OverlayView overlayView;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);

        surfaceView = new SurfaceView(this);
        overlayView = new OverlayView(this);
        setContentView(surfaceView);
        addContentView(overlayView, new WindowManager.LayoutParams(
            WindowManager.LayoutParams.MATCH_PARENT,
            WindowManager.LayoutParams.MATCH_PARENT));

        runScript("init_env.sh");
        runScript("start_stronghold3.sh");
    }

    private void runScript(String scriptName) {
        try {
            ProcessBuilder pb = new ProcessBuilder("sh", getFilesDir() + "/" + scriptName);
            pb.environment().put("APP_ROOT", APP_ROOT);
            pb.environment().put("GAME_DIR", "/sdcard/Stronghold3");
            pb.redirectErrorStream(true);
            Process proc = pb.start();
            InputStream in = proc.getInputStream();
            OutputStream out = new FileOutputStream(getFilesDir() + "/" + scriptName + ".log");
            byte[] buf = new byte[4096];
            int n;
            while ((n = in.read(buf)) > 0) out.write(buf, 0, n);
            out.close();
            proc.waitFor();
        } catch (Exception e) {
            android.util.Log.e(TAG, "Failed to run " + scriptName, e);
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        // Wine/DXVK processes are killed when the rootfs session ends.
        try {
            Runtime.getRuntime().exec(new String[]{"sh", "-c", "pkill -f wine || true"});
        } catch (Exception ignored) {}
    }
}
